import{_ as o,C as i,c as l,o as c,a3 as n,G as s,j as t,a as r}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Create a maintenance request","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/maintenance/requests/create-request.md","filePath":"master/supply-chain/maintenance/requests/create-request.md","lastUpdated":1793074831000}'),u={name:"master/supply-chain/maintenance/requests/create-request.md"};function g(h,e,d,m,p,q){const a=i("ImagePopup");return c(),l("div",null,[e[0]||(e[0]=n('<h1 id="create-a-maintenance-request" tabindex="-1">Create a maintenance request <a class="header-anchor" href="#create-a-maintenance-request" aria-label="Permalink to &quot;Create a maintenance request&quot;">​</a></h1><p>A maintenance request tells your team that a machine needs work. You pick the equipment, describe the problem, choose a type and say who should do it. Aureus then fills in most of the other fields for you.</p><blockquote><p><strong>In simple words:</strong> Choose the equipment, type a short title, and save. Add a date and instructions so the technician knows what to do.</p></blockquote><p>Open <code>Maintenance → Maintenance Requests</code> and click <strong>New Maintenance Request</strong>.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><p>Create these records first:</p><ul><li>A <a href="./../setup/maintenance-teams.html">maintenance team</a>.</li><li>The <a href="./../setup/stages.html">stages</a>. Aureus puts a new request in the first stage.</li><li>The <a href="./../equipment/add-equipment.html">equipment</a> that needs work.</li></ul></div><h2 id="worked-example" tabindex="-1">Worked example <a class="header-anchor" href="#worked-example" aria-label="Permalink to &quot;Worked example&quot;">​</a></h2><p>The <strong>Hydraulic Press 200T</strong> leaks oil. You raise a corrective request for it.</p><ol><li>Open <code>Maintenance → Maintenance Requests</code>. Click <strong>New Maintenance Request</strong>. The page is titled <strong>Create Maintenance Request</strong>.</li></ol>',8)),s(a,{src:"/images1/maintenance/req_create_empty.png",alt:"Empty Create Maintenance Request form with New Request highlighted in the stage bar, the Request card, tabs and Settings card"}),e[1]||(e[1]=n('<ol start="2"><li>Look at the stage bar at the top. It shows <strong>New Request</strong>, <strong>In Progress</strong>, <strong>Repaired</strong> and <strong>Scrap</strong>. A new request starts in <strong>New Request</strong>.</li></ol><h3 id="request-card" tabindex="-1">Request card <a class="header-anchor" href="#request-card" aria-label="Permalink to &quot;Request card&quot;">​</a></h3><ol start="3"><li>Type the title in <strong>Request</strong>. Write <strong>Hydraulic press oil leak</strong>.</li><li>Choose <strong>Hydraulic Press 200T</strong> in <strong>Equipment</strong>. Aureus fills several fields at once.</li></ol>',3)),s(a,{src:"/images1/maintenance/req_create_equipment_autofill.png",alt:"Request form titled Hydraulic press oil leak after choosing Hydraulic Press 200T, with Category Packaging Machines, Team Electrical Maintenance Team and Responsible Linda Ndlovu filled automatically"}),e[2]||(e[2]=n('<ol start="5"><li>Leave <strong>Maintenance Type</strong> on <strong>Corrective</strong>.</li></ol><ul><li><strong><em>Request:</em></strong> Required. A short title, up to 255 characters. You cannot change it after you save.</li><li><strong><em>Equipment:</em></strong> The machine that needs work. Pick it from the list.</li><li><strong><em>Category:</em></strong> Filled from the equipment. You cannot edit it here. Example: <strong>Packaging Machines</strong>.</li><li><strong><em>Request Date:</em></strong> Filled by Aureus. It starts as today and changes to the date of the equipment you pick. You cannot edit it.</li><li><strong><em>Maintenance Type:</em></strong> <strong>Corrective</strong> (default) or <strong>Preventive</strong>. Choose <strong>Preventive</strong> to see the <strong>Recurrent</strong> box. See <a href="./preventive-maintenance.html">Preventive maintenance</a>.</li></ul><h3 id="settings-card" tabindex="-1">Settings card <a class="header-anchor" href="#settings-card" aria-label="Permalink to &quot;Settings card&quot;">​</a></h3><ol start="6"><li>Check the <strong>Settings</strong> card on the right. Equipment filled <strong>Team</strong> and <strong>Responsible</strong>.</li><li>Set <strong>Scheduled Date</strong> to a near future date at 09:00, for example <strong>Oct 14, 2026 09:00</strong>. Set <strong>Duration</strong> to <strong>02:00</strong>. Set <strong>Priority</strong> to <strong>2</strong>.</li></ol>',4)),s(a,{src:"/images1/maintenance/req_create_settings.png",alt:"Settings card with Team Electrical Maintenance Team, Responsible Linda Ndlovu, Scheduled Date Oct 14, 2026 09:00:00, Duration 02:00 and Priority 2"}),e[3]||(e[3]=n('<ul><li><strong><em>Team:</em></strong> Required. Filled from the equipment. Example: <strong>Electrical Maintenance Team</strong>.</li><li><strong><em>Responsible:</em></strong> The technician. Filled from the equipment. Example: <strong>Linda Ndlovu</strong>. Without equipment it is you.</li><li><strong><em>Scheduled Date:</em></strong> When the work should start. Requests with a date show on the <a href="./../calendar/maintenance-calendar.html">calendar</a>.</li><li><strong><em>Duration:</em></strong> How long the job takes, as hours and minutes (<code>hh:mm</code>). Example: <code>02:00</code>.</li><li><strong><em>Priority:</em></strong> A number from 0 to 3. The default is 0. Use 0 for normal work and 1 to 3 for work that needs attention first. Any value above 0 appears in the <strong>High-priority</strong> tab.</li><li><strong><em>Company:</em></strong> Required. The default is your company.</li></ul><h3 id="notes-tab" tabindex="-1">Notes tab <a class="header-anchor" href="#notes-tab" aria-label="Permalink to &quot;Notes tab&quot;">​</a></h3><ol start="8"><li>The <strong>Notes</strong> tab is open by default. Type extra details in <strong>Internal Notes</strong>. Only your team sees them.</li></ol><h3 id="instructions-tab" tabindex="-1">Instructions tab <a class="header-anchor" href="#instructions-tab" aria-label="Permalink to &quot;Instructions tab&quot;">​</a></h3><ol start="9"><li>Open the <strong>Instructions</strong> tab. <strong>Instruction Type</strong> is <strong>Text</strong> by default.</li></ol><ul><li><strong>Text:</strong> shows a <strong>Description</strong> box. Type the steps.</li><li><strong>PDF:</strong> shows a <strong>PDF</strong> upload. Attach a manual or checklist.</li><li><strong>Google Slide:</strong> shows a <strong>Google Slide</strong> field. Paste the link of the presentation.</li></ul><p>For the example, keep <strong>Text</strong> and write: <em>Isolate the power, replace the gasket, refill oil to the marked level</em>.</p>',7)),s(a,{src:"/images1/maintenance/req_create_instructions.png",alt:"Instructions tab with Instruction Type Text and the repair steps typed in Description"}),e[4]||(e[4]=t("h3",{id:"save",tabindex:"-1"},[r("Save "),t("a",{class:"header-anchor",href:"#save","aria-label":'Permalink to "Save"'},"​")],-1)),e[5]||(e[5]=t("ol",{start:"10"},[t("li",null,[r("Click "),t("strong",null,"Create"),r(". Click "),t("strong",null,"Create & create another"),r(" to start a new form. Click "),t("strong",null,"Cancel"),r(" to leave.")])],-1)),s(a,{src:"/images1/maintenance/req_create_filled.png",alt:"Completed Hydraulic press oil leak request for Hydraulic Press 200T, Corrective, ready to save"}),e[6]||(e[6]=n('<p>After <strong>Create</strong> the notification <strong>Maintenance request created</strong> appears with the text &quot;The maintenance request has been created successfully.&quot; You land on the <strong>View</strong> page of the new request, not the list. The <strong>Chatter</strong> badge shows 1, for &quot;A new Maintenance Request was created&quot;.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Pick the equipment first. It fills <strong>Category</strong>, <strong>Team</strong> and <strong>Responsible</strong>, so you type less.</p></div><h2 id="what-happens-next" tabindex="-1">What happens next <a class="header-anchor" href="#what-happens-next" aria-label="Permalink to &quot;What happens next&quot;">​</a></h2><p>The request sits in <strong>New Request</strong> and is assigned to <strong>Linda Ndlovu</strong>. Move it forward in <a href="./process-request.html">Process a request</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Maintenance requests</a></li><li><a href="./preventive-maintenance.html">Preventive maintenance</a></li><li><a href="./request-list.html">Maintenance request list</a></li><li><a href="./../equipment/add-equipment.html">Add equipment</a></li></ul>',6))])}const T=o(u,[["render",g]]);export{_ as __pageData,T as default};
